requires n > 0
ensures (n <= 0) || (0 <= m && m < n)
{
    x := 0;
    m := 0;

    while(x < n)
        invariant 0 <= x <= n
        invariant 0 <= m < (n) + 1
    {
        if(*)
        {
            m := x;
        }
        else{}
        x := x + 1;
    }
}

